// Dev-only: stock rows for the products generated by the backend's
// `php artisan perf:seed`, so load tests can place orders without running out.
//
//   npm run seed:perf -- --products=50000 --available=1000000 [--fresh]
//
// The product ids follow the same formula as perf:seed (n in the first group,
// marker 8f00 in the fourth): 0000000c-0000-4000-8f00-000000000000 is product 12.
// Run it AFTER perf:seed, with the same --products value.
//
// Without --fresh, missing rows are added and existing ones are left alone.
// With --fresh, reservations that touch perf products are deleted (their
// items go with them) and every perf product's stock is set back to
// --available, so each measurement starts from the same state. Rows of other
// products are never touched.
const pool = require('./db');

const PRODUCT_KIND = '8f00';

function parseArgs(argv) {
  const opts = { products: 50000, available: 1000000, fresh: false };
  for (const arg of argv) {
    const m = /^--([a-z]+)(?:=(.*))?$/.exec(arg);
    if (!m) throw new Error(`unknown argument: ${arg}`);
    const [, key, value] = m;
    if (key === 'fresh') {
      opts.fresh = true;
    } else if (key === 'products' || key === 'available') {
      const n = Number(value);
      if (!Number.isInteger(n) || n < 1) throw new Error(`--${key} must be a positive integer`);
      opts[key] = n;
    } else {
      throw new Error(`unknown option: --${key}`);
    }
  }
  return opts;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const startedAt = Date.now();
  const log = (msg) => console.log(`[${((Date.now() - startedAt) / 1000).toFixed(1).padStart(6)}s] ${msg}`);

  const { rows } = await pool.query('SELECT current_database() AS db');
  log(`seed:perf on database "${rows[0].db}": ${opts.products} products, ${opts.available} available each${opts.fresh ? ', fresh' : ''}`);

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    if (opts.fresh) {
      const res = await client.query(
        `DELETE FROM reservations
          WHERE id IN (SELECT reservation_id FROM reservation_items
                        WHERE substr(product_id::text, 20, 4) = $1)`,
        [PRODUCT_KIND]
      );
      log(`removed ${res.rowCount} reservations of perf products`);
    }

    const res = await client.query(
      `INSERT INTO stock (product_id, available)
       SELECT (lpad(to_hex(n), 8, '0') || '-0000-4000-' || $1 || '-000000000000')::uuid, $2
         FROM generate_series(1, $3::int) AS n
       ON CONFLICT (product_id) DO ${opts.fresh ? 'UPDATE SET available = EXCLUDED.available, updated_at = NOW()' : 'NOTHING'}`,
      [PRODUCT_KIND, opts.available, opts.products]
    );
    log(`${opts.fresh ? 'set' : 'inserted'} ${res.rowCount} stock rows`);

    if (opts.fresh) {
      // Perf products beyond --products (from an earlier, bigger run) go away.
      const extra = await client.query(
        `DELETE FROM stock
          WHERE substr(product_id::text, 20, 4) = $1
            AND ('x' || substr(product_id::text, 1, 8))::bit(32)::bigint > $2`,
        [PRODUCT_KIND, opts.products]
      );
      if (extra.rowCount > 0) log(`removed ${extra.rowCount} stock rows beyond --products`);
    }

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }

  await pool.query('VACUUM ANALYZE stock');
  if (opts.fresh) await pool.query('VACUUM ANALYZE reservations');
  if (opts.fresh) await pool.query('VACUUM ANALYZE reservation_items');
  log('done');
}

main()
  .catch((err) => {
    console.error(`seed:perf failed: ${err.message}`);
    process.exitCode = 1;
  })
  .finally(() => pool.end());
